    29	import static org.apache.hadoop.hdfs.server.federation.fairness.RouterRpcFairnessConstants.CONCURRENT_NS;
    30	import static org.apache.hadoop.hdfs.server.federation.router.RBFConfigKeys.DFS_ROUTER_HANDLER_COUNT_KEY;
    31	import static org.apache.hadoop.hdfs.server.federation.router.RBFConfigKeys.DFS_ROUTER_HANDLER_COUNT_DEFAULT;
    32	import static org.apache.hadoop.hdfs.server.federation.router.RBFConfigKeys.DFS_ROUTER_FAIR_HANDLER_COUNT_KEY_PREFIX;
    33	
    34	/**
    35	 * Static fairness policy extending @AbstractRouterRpcFairnessPolicyController
    36	 * and fetching handlers from configuration for all available name services.
    37	 * The handlers count will not change for this controller.
    38	 */
    39	public class StaticRouterRpcFairnessPolicyController extends
    40	    AbstractRouterRpcFairnessPolicyController {
    41	
    42	  private static final Logger LOG =
    43	      LoggerFactory.getLogger(StaticRouterRpcFairnessPolicyController.class);
    44	
    45	  public static final String ERROR_MSG = "Configured handlers "
    46	      + DFS_ROUTER_HANDLER_COUNT_KEY + '='
    47	      + " %d is less than the minimum required handlers %d";
    48	
    49	  public StaticRouterRpcFairnessPolicyController(Configuration conf) {
    50	    init(conf);
    51	  }
    52	
    53	  public void init(Configuration conf)
    54	      throws IllegalArgumentException {
    55	    super.init(conf);
    56	    // Total handlers configured to process all incoming Rpc.
    57	    int handlerCount = conf.getInt(
    58	        DFS_ROUTER_HANDLER_COUNT_KEY,
    59	        DFS_ROUTER_HANDLER_COUNT_DEFAULT);
    60	
    61	    LOG.info("Handlers available for fairness assignment {} ", handlerCount);
    62	
    63	    // Get all name services configured
    64	    Set<String> allConfiguredNS = FederationUtil.getAllConfiguredNS(conf);
    65	
    66	    // Set to hold name services that are not
    67	    // configured with dedicated handlers.
    68	    Set<String> unassignedNS = new HashSet<>();
    69	
    70	    // Insert the concurrent nameservice into the set to process together
    71	    allConfiguredNS.add(CONCURRENT_NS);
    72	    validateHandlersCount(conf, handlerCount, allConfiguredNS);
    73	    for (String nsId : allConfiguredNS) {
    74	      int dedicatedHandlers =
    75	          conf.getInt(DFS_ROUTER_FAIR_HANDLER_COUNT_KEY_PREFIX + nsId, 0);
    76	      LOG.info("Dedicated handlers {} for ns {} ", dedicatedHandlers, nsId);
    77	      if (dedicatedHandlers > 0) {
    78	        handlerCount -= dedicatedHandlers;
    79	        insertNameServiceWithPermits(nsId, dedicatedHandlers);
    80	        logAssignment(nsId, dedicatedHandlers);
    81	      } else {
    82	        unassignedNS.add(nsId);
    83	      }
    84	    }
    85	
    86	    // Assign remaining handlers equally to remaining name services and
    87	    // general pool if applicable.
    88	    if (!unassignedNS.isEmpty()) {
    89	      LOG.info("Unassigned ns {}", unassignedNS.toString());
    90	      int handlersPerNS = handlerCount / unassignedNS.size();
    91	      LOG.info("Handlers available per ns {}", handlersPerNS);
    92	      for (String nsId : unassignedNS) {
    93	        insertNameServiceWithPermits(nsId, handlersPerNS);
    94	        logAssignment(nsId, handlersPerNS);
    95	      }
    96	    }
    97	
    98	    // Assign remaining handlers if any to fan out calls.
    99	    int leftOverHandlers = handlerCount % unassignedNS.size();
   100	    int existingPermits = getAvailablePermits(CONCURRENT_NS);
   101	    if (leftOverHandlers > 0) {
   102	      LOG.info("Assigned extra {} handlers to commons pool", leftOverHandlers);
   103	      insertNameServiceWithPermits(CONCURRENT_NS,
   104	          existingPermits + leftOverHandlers);
   105	    }
   106	    LOG.info("Final permit allocation for concurrent ns: {}",
   107	        getAvailablePermits(CONCURRENT_NS));
   108	  }
   109	
   110	  private static void logAssignment(String nsId, int count) {
   111	    LOG.info("Assigned {} handlers to nsId {} ",
   112	        count, nsId);
   113	  }
   114	
   115	  private void validateHandlersCount(Configuration conf, int handlerCount,
   116	                                     Set<String> allConfiguredNS) {
   117	    int totalDedicatedHandlers = 0;
   118	    for (String nsId : allConfiguredNS) {
   119	      int dedicatedHandlers =
   120	              conf.getInt(DFS_ROUTER_FAIR_HANDLER_COUNT_KEY_PREFIX + nsId, 0);
   121	      if (dedicatedHandlers > 0) {
   122	        // Total handlers should not be less than sum of dedicated handlers.
   123	        totalDedicatedHandlers += dedicatedHandlers;
   124	      } else {
   125	        // Each NS should have at least one handler assigned.
   126	        totalDedicatedHandlers++;
   127	      }
   128	    }
   129	    if (totalDedicatedHandlers > handlerCount) {
   130	      String msg = String.format(ERROR_MSG, handlerCount,
   131	          totalDedicatedHandlers);
   132	      LOG.error(msg);
   133	      throw new IllegalArgumentException(msg);
   134	    }
   135	  }
   136	
   137	}

