133	  private void verifyHandlerAllocation(
134	      RouterRpcFairnessPolicyController routerRpcFairnessPolicyController) {
135	    for (int i=0; i<10; i++) {
136	      assertTrue(routerRpcFairnessPolicyController.acquirePermit("ns1"));
137	      assertTrue(routerRpcFairnessPolicyController.acquirePermit("ns2"));
138	      assertTrue(
139	          routerRpcFairnessPolicyController.acquirePermit(CONCURRENT_NS));
140	    }
141	    assertFalse(routerRpcFairnessPolicyController.acquirePermit("ns1"));
142	    assertFalse(routerRpcFairnessPolicyController.acquirePermit("ns2"));
143	    assertFalse(routerRpcFairnessPolicyController.acquirePermit(CONCURRENT_NS));
144	
145	    routerRpcFairnessPolicyController.releasePermit("ns1");
146	    routerRpcFairnessPolicyController.releasePermit("ns2");
147	    routerRpcFairnessPolicyController.releasePermit(CONCURRENT_NS);
148	
149	    assertTrue(routerRpcFairnessPolicyController.acquirePermit("ns1"));
150	    assertTrue(routerRpcFairnessPolicyController.acquirePermit("ns2"));
151	    assertTrue(routerRpcFairnessPolicyController.acquirePermit(CONCURRENT_NS));
152	  }
